/**
 * Restore MongoDB backup generated by scripts/backup-db-full.js
 *
 * Usage:
 *   node scripts/restore-db-full.js --from backup/full/2026-05-06T10-30-00 --uri "<TARGET_URI>" --drop true
 *
 * Notes:
 * - --drop true: drops each target collection before restore.
 * - Restores all docs + indexes (except default _id index recreation).
 */
const fs = require("fs");
const path = require("path");
const mongoose = require("mongoose");
// EJSON via mongoose's bundled bson (avoids a direct "bson" dependency).
const { EJSON } = mongoose.mongo.BSON;

const projectRoot = path.resolve(__dirname, "..");
require("dotenv").config({ path: path.join(projectRoot, ".env.local") });
require("dotenv").config({ path: path.join(projectRoot, ".env") });

function parseArgs(argv) {
  const out = {};
  for (let i = 2; i < argv.length; i += 1) {
    const arg = argv[i];
    if (!arg.startsWith("--")) continue;
    const key = arg.slice(2);
    const value = argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[++i] : "true";
    out[key] = value;
  }
  return out;
}

function maskMongoUri(uri) {
  if (!uri) return "";
  return uri.replace(/:\/\/([^:]+):([^@]+)@/, "://$1:***@");
}

function toBool(value, fallback = false) {
  if (typeof value === "boolean") return value;
  const text = String(value ?? "").trim().toLowerCase();
  if (text === "true" || text === "1" || text === "yes") return true;
  if (text === "false" || text === "0" || text === "no") return false;
  return fallback;
}

function readEjsonArray(filePath) {
  const raw = fs.readFileSync(filePath, "utf8");
  const parsed = EJSON.parse(raw);
  return Array.isArray(parsed) ? parsed : [];
}

async function insertInBatches(collection, docs, batchSize = 500) {
  if (!Array.isArray(docs) || docs.length === 0) return 0;
  let inserted = 0;
  for (let i = 0; i < docs.length; i += batchSize) {
    const chunk = docs.slice(i, i + batchSize);
    if (chunk.length > 0) {
      await collection.insertMany(chunk, { ordered: false });
      inserted += chunk.length;
    }
  }
  return inserted;
}

async function run() {
  const args = parseArgs(process.argv);
  const fromDirArg = args.from;
  const uri = args.uri || process.env.MONGODB_URI;
  const shouldDrop = toBool(args.drop, false);

  if (!fromDirArg) {
    throw new Error("Missing --from <backup-directory>.");
  }
  if (!uri) {
    throw new Error("Missing target URI. Pass --uri or set MONGODB_URI.");
  }

  const fromDir = path.resolve(projectRoot, fromDirArg);
  if (!fs.existsSync(fromDir)) {
    throw new Error(`Backup directory not found: ${fromDir}`);
  }

  console.log("Source dir :", fromDir);
  console.log("Target URI :", maskMongoUri(uri));
  console.log("Drop mode  :", shouldDrop ? "ON" : "OFF");

  const files = fs.readdirSync(fromDir);
  const docFiles = files
    .filter((name) => name.endsWith(".ejson"))
    .filter((name) => !name.endsWith("._indexes.ejson"))
    .filter((name) => !name.startsWith("_"))
    .sort();

  const conn = await mongoose.createConnection(uri).asPromise();
  const db = conn.db;

  for (const docFile of docFiles) {
    const collectionName = docFile.replace(/\.ejson$/, "");
    const docsPath = path.join(fromDir, docFile);
    const indexesPath = path.join(fromDir, `${collectionName}._indexes.ejson`);

    const docs = readEjsonArray(docsPath);
    const indexes = fs.existsSync(indexesPath)
      ? readEjsonArray(indexesPath)
      : [];

    const collection = db.collection(collectionName);

    if (shouldDrop) {
      const existing = await db
        .listCollections({ name: collectionName })
        .hasNext();
      if (existing) {
        await collection.drop();
        console.log(`DROP ${collectionName}`);
      }
    }

    const inserted = await insertInBatches(collection, docs);

    const indexSpecs = indexes
      .filter((idx) => idx && typeof idx === "object")
      .filter((idx) => idx.name && idx.name !== "_id_")
      .map((idx) => {
        const opts = { ...idx };
        delete opts.key;
        return { key: idx.key, ...opts };
      });

    if (indexSpecs.length > 0) {
      try {
        await collection.createIndexes(indexSpecs);
      } catch (err) {
        console.warn(`WARN indexes ${collectionName}: ${err.message}`);
      }
    }

    console.log(
      `OK ${collectionName}: inserted=${inserted}, indexes=${indexSpecs.length}`,
    );
  }

  await conn.close();
  console.log("\nRestore complete.");
}

run().catch(async (err) => {
  try {
    await mongoose.disconnect();
  } catch {}
  console.error("Restore failed:", err.message);
  process.exit(1);
});

